from dataclasses import dataclass
from collections.abc import Sequence
import copy
import math


@dataclass
class Transition:
    state: object
    action: int
    reward: float
    next_state: object
    done: bool


class ReplayBuffer:
    def __init__(self, capacity):
        if isinstance(capacity, bool) or not isinstance(capacity, int):
            raise TypeError("capacity must be an integer")
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._items = []

    def add(self, transition):
        if not isinstance(transition, Transition):
            raise TypeError("transition must be a Transition")
        self._items.append(copy.copy(transition))
        if len(self._items) > self.capacity:
            del self._items[0]

    def sample(self, indices):
        try:
            requested = list(indices)
        except TypeError as exc:
            raise TypeError("indices must be iterable") from exc
        result = []
        for index in requested:
            if isinstance(index, bool) or not isinstance(index, int):
                raise TypeError("indices must be integers")
            if index < 0 or index >= len(self._items):
                raise IndexError("buffer index out of range")
            result.append(copy.deepcopy(self._items[index]))
        return result

    def __len__(self):
        return len(self._items)


def _validate_action(action):
    if isinstance(action, bool) or not isinstance(action, int):
        raise TypeError("action must be an integer")
    if action < 0:
        raise ValueError("action must be non-negative")


def _scores(model, state):
    output = model(state)
    if isinstance(output, (str, bytes, bytearray)) or not isinstance(output, Sequence):
        raise ValueError("model output must be a sequence")
    if len(output) == 0:
        raise ValueError("model output must not be empty")
    values = list(output)
    for value in values:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("model values must be numeric")
        if not math.isfinite(value):
            raise ValueError("model values must be finite")
    return values


class _Controller:
    def __init__(self, buffer):
        if not isinstance(buffer, ReplayBuffer):
            raise TypeError("buffer must be a ReplayBuffer")
        self.buffer = buffer

    def step(self, environment, draw=0.0):
        state = copy.deepcopy(environment.state)
        action = self.act(state, draw)
        next_state, reward, done = environment.advance(action)
        transition = Transition(state, action, reward, next_state, bool(done))
        self.buffer.add(transition)
        return reward, bool(done)


class ConstantController(_Controller):
    def __init__(self, action, buffer):
        _validate_action(action)
        super().__init__(buffer)
        self.action = action

    def act(self, state, draw=0.0):
        return self.action


class ScoreController(_Controller):
    def __init__(self, model, buffer):
        if not callable(model):
            raise TypeError("model must be callable")
        super().__init__(buffer)
        self.model = model

    def act(self, state, draw=0.0):
        values = _scores(self.model, state)
        return max(range(len(values)), key=values.__getitem__)


class DistributionController(_Controller):
    def __init__(self, model, buffer):
        if not callable(model):
            raise TypeError("model must be callable")
        super().__init__(buffer)
        self.model = model

    def act(self, state, draw=0.0):
        if isinstance(draw, bool) or not isinstance(draw, (int, float)):
            raise TypeError("draw must be numeric")
        if not math.isfinite(draw) or draw < 0 or draw >= 1:
            raise ValueError("draw must be in [0, 1)")
        weights = _scores(self.model, state)
        if any(weight < 0 for weight in weights):
            raise ValueError("weights must be non-negative")
        scale = max(weights)
        if scale <= 0:
            raise ValueError("weights must have a positive sum")
        scaled = [weight / scale for weight in weights]
        total = math.fsum(scaled)
        target = draw * total
        cumulative = 0.0
        for index, weight in enumerate(scaled):
            cumulative += weight
            if target < cumulative:
                return index
        return max(index for index, weight in enumerate(weights) if weight > 0)

